create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_REAL_ESTATE_1 (
	REAL_ESTATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the real estate object.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	REAL_ESTATE_NR VARCHAR(20) COMMENT 'The number which uniquely identifies a real estate object within a country_1 organization.',
	REAL_ESTATE_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the real estate object.',
	REAL_ESTATE_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for real estate objects.',
	REAL_ESTATE_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the subtype discriminator for real estate objects. (Description in group language, i.e. in German)',
	REAL_ESTATE_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the lifecycle status_1 for real estate objects. (This is the business lifecycle, so it might differ from the status_1 code shown in the source system.)',
	REAL_ESTATE_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the lifecycle status_1 for real estate objects. (Description in group language, i.e. in German)',
	INT_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the internal organization, which is located in this real estate object.',
	CURR_INT_ORG_NR VARCHAR(20) NOT NULL COMMENT 'The current number of the internal organization, which is located in this real estate object.. (This number may change over time)',
	INT_ORG_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the internal organization, which is located in this real estate object.',
	INT_ORG_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the discriminators for the internal organization, which is located in this real estate object.',
	INT_ORG_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the discriminators for internal organizations. (Description in group language, i.e. in German)',
	OWNERSHIP_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the ownership type of a real estate object, i.e. if it has been bought or if it is rented.',
	OWNERSHIP_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the ownership type of a real estate object, (Description in group language, i.e. in German)',
	OWNERSHIP_RATIO_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the ownership ratio of a real estate object, i.e. if it is fully owned or partly owned.',
	OWNERSHIP_RATIO_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the ownership ratio of a real estate object, (Description in group language, i.e. in German)',
	OWN_ACQUISITION_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the real estate object was acquired by the Schwarz Group without involvement of a third party.',
	REAL_ESTATE_USG_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the way, how a real estate object is used. An object may be used by the organization or by a third party.',
	REAL_ESTATE_USG_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the way, how a real estate object is used. An object may be used by the organization or by a third party. (Description in group language, i.e. in German)',
	REPLACEMENT_REAL_ESTATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) of the real estate object which replaces this object.',
	REPLACEMENT_REAL_ESTATE_NR VARCHAR(20) COMMENT 'The number which uniquely identifies the real estate object which replaces this object.',
	REPLACEMENT_REAL_ESTATE_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the real estate object which replaces this object.',
	REAL_ESTATE_REPLACEMENT_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the way, how a real estate object can replace another object. There are two types of replacments: Relocations and demolition and a new construction.',
	REAL_ESTATE_REPLACEMENT_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the way, how a real estate object can replace another object. (Description in group language, i.e. in German)',
	WH_BUILDING_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the subtype discriminator for warehouse building.',
	WH_BUILDING_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the subtype discriminator for warehouse buildings. (Description in group language, i.e. in German)',
	WH_PURPOSE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the purpose of a warehouse.',
	WH_PURPOSE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the purpose of a warehouse. (Description in group language, i.e. in German)',
	SHARED_USG_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the warehouse is used by multiple parties.',
	ISO_COUNTRY_CD VARCHAR(2) NOT NULL COMMENT 'The code according to ISO 3166 identifying the country_1, in which the real estate object is located,',
	COUNTRY_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the country_1, in which the real estate object is located,',
	CITY_NAME VARCHAR(100) COMMENT 'The name of the city, in which the real estate object is located,',
	DISTRICT_NAME VARCHAR(100) COMMENT 'The name of the district, in which the real estate object is located,',
	ZIP VARCHAR(15) COMMENT 'The zip code for the address_1 of the real estate object.',
	STREET_NAME VARCHAR(100) COMMENT 'The name of the street, in which the real estate object is located. (This includes names of squares and similar locations.)',
	HOUSE_NR VARCHAR(100) COMMENT 'The house number for the real estate object.',
	LON NUMBER(9,6) COMMENT 'The longitude component of the geographical coordinates of the address_1 of the real estate object.',
	LAT NUMBER(9,6) COMMENT 'The latitude component of the geographical coordinates of the address_1 of the real estate object.',
	PO_BOX_NR VARCHAR(20) COMMENT 'The number of a post office box, which is used for this real estate object.',
	PHONE_NR VARCHAR(100) COMMENT 'The telephone number for that real estate object.',
	FAX_NR VARCHAR(100) COMMENT 'The fax number for that real estate object.',
	EMAIL_ADDR_TXT VARCHAR(1000) COMMENT 'An email address_1 for that real estate object.',
	REPORTING_COUNTRY_CD VARCHAR(20) NOT NULL COMMENT 'The code which identifies the reporting country_1 in which the real estate object is located.',
	REPORTING_COUNTRY_NAME VARCHAR(100) NOT NULL COMMENT 'The name the reporting country. (i.e. a country_1 definition which is different from a geographical country_1) The name in in group lanuage, i.e. in German. (Name in group language, i.e. in German)',
	SALES_AREA_MEAS NUMBER(38,5) COMMENT 'The space which can be used for sales_1, in the unit_1 indicated by the unit_1 of measure code (e.g. m2).',
	STORAGE_AREA_MEAS NUMBER(38,5) COMMENT 'The space which can be used for storing goods, in the unit_1 indicated by the unit_1 of measure code (e.g. m2).',
	TOTAL_SUBLET_AREA_MEAS NUMBER(38,5) COMMENT 'The total space which can be sublet, in the unit_1 indicated by the unit_1 of measure code (e.g. m2).',
	RENTED_SUBLET_AREA_MEAS NUMBER(38,5) COMMENT 'The space which is currently rented out, in the unit_1 indicated by the unit_1 of measure code.',
	UOM_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the unit_1 of measure for the sales_1 area.',
	SALES_AREA_M2_MEAS NUMBER(38,5) COMMENT 'The space in square meters which can be used for sales.',
	STORAGE_AREA_M2_MEAS NUMBER(38,5) COMMENT 'The space in square meters, which can be used for storing goods.',
	TOTAL_SUBLET_AREA_M2_MEAS NUMBER(38,5) COMMENT 'The total space in square meters, which can be sublet.',
	RENTED_SUBLET_AREA_M2_MEAS NUMBER(38,5) COMMENT 'The space in square meters, which is currently rented out.',
	TOTAL_PARKING_SPACE_CNT NUMBER(38,0) COMMENT 'The total number of parking spaces that are assigned to this building.',
	OWN_PARKING_SPACE_CNT NUMBER(38,0) COMMENT 'The number of parking spaces that are assigned to this building and which are owned by the Schwarz Group.',
	UNDERGROUND_PARKING_SPACE_CNT NUMBER(38,0) COMMENT 'The total number of parking spaces in an underground parking garage that are assigned to this building.',
	RENTAL_COST_VAL NUMBER(38,5) COMMENT 'The rental cost for this real estate object per year. (in the currency indicated by the currency code)',
	RENTAL_INCOME_VAL NUMBER(38,5) COMMENT 'The rental income for this real estate object per year. (in the currency indicated by the currency code)',
	CURR_CD VARCHAR(3) NOT NULL COMMENT 'The code identifying the currency according to ISO-4217.',
	RENTAL_COST_EUR_VAL NUMBER(38,5) COMMENT 'The rental cost in Euro for this real estate object per year.',
	RENTAL_INCOME_EUR_VAL NUMBER(38,5) COMMENT 'The rental income in Euro for this real estate object per year.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_REAL_ESTATE primary key (REAL_ESTATE_SID, DWH_VALID_FROM_TMSP)
)COMMENT='Real Estate is property in the form of land_1 or buildings.'
;